from pathlib import Path
p=Path('restoration/scripts/finish.mjs');s=p.read_text(encoding='utf-8-sig')
s=s.replace("await doc.transform(dedup(),prune({keepLeaves:true,keepAttributes:false,keepSolidTextures:true}),weld(),palette({min:2}),join({keepNamed:true}),dedup(),prune({keepLeaves:true,keepSolidTextures:true}));", "const ownArt=id.startsWith('crossfader-');\nif(ownArt)for(const m of doc.getRoot().listMaterials()){\n const src=source.getRoot().listMaterials().find(s=>s.getName()===m.getName());\n if(src)m.setBaseColorFactor(src.getBaseColorFactor()).setMetallicFactor(src.getMetallicFactor()).setRoughnessFactor(src.getRoughnessFactor()).setEmissiveFactor(src.getEmissiveFactor()).setDoubleSided(src.getDoubleSided());\n}\nawait doc.transform(dedup(),prune({keepLeaves:true,keepAttributes:false,keepSolidTextures:true}),weld());\nif(!ownArt)await doc.transform(palette({min:2}));\nawait doc.transform(join({keepNamed:true}),dedup(),prune({keepLeaves:true,keepSolidTextures:true}));")
s=s.replace('doc.createExtension(EXTTextureWebP).setRequired(true);', 'if(doc.getRoot().listTextures().length)doc.createExtension(EXTTextureWebP).setRequired(true);')
s=s.replace('const checks={screens:', "const ownColorChecks=ownArt?source.getRoot().listMaterials().map(s=>{const t=final.getRoot().listMaterials().find(m=>m.getName()===s.getName());return {name:s.getName(),equal:!!t&&JSON.stringify(s.getBaseColorFactor())===JSON.stringify(t.getBaseColorFactor())};}):[];\nconst checks={ownColors:ownColorChecks.every(c=>c.equal),screens:")
s=s.replace('art,nodeChecks,screenChecks,checks};', 'art,nodeChecks,screenChecks,ownColorChecks,checks};')
